"""Modelo de producto y reglas de validación monetaria."""

from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re


PRECISION_MONETARIA = Decimal("0.01")


def redondear_monetario(importe: Decimal) -> Decimal:
    """Redondea un importe a céntimos con un criterio uniforme."""
    return importe.quantize(PRECISION_MONETARIA, rounding=ROUND_HALF_UP)


def _convertir_precio(precio: Decimal | int | float | str) -> Decimal:
    if isinstance(precio, bool):
        raise ValueError("El precio debe ser numérico.")

    try:
        importe = precio if isinstance(precio, Decimal) else Decimal(str(precio))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError("El precio debe ser numérico.") from exc

    if not importe.is_finite():
        raise ValueError("El precio debe ser finito.")
    if importe < 0:
        raise ValueError("El precio no puede ser negativo.")

    try:
        return redondear_monetario(importe)
    except InvalidOperation as exc:
        raise ValueError("El precio está fuera del rango admitido.") from exc


@dataclass(frozen=True, slots=True)
class Producto:
    """Producto inmutable del catálogo."""

    id: str
    nombre: str
    precio: Decimal | int | float | str
    moneda: str = "EUR"
    stock: int = 0

    def __post_init__(self) -> None:
        if not isinstance(self.id, str) or not self.id.strip():
            raise ValueError("El identificador del producto es obligatorio.")
        if not isinstance(self.nombre, str) or not self.nombre.strip():
            raise ValueError("El nombre del producto es obligatorio.")
        if not isinstance(self.stock, int) or isinstance(self.stock, bool):
            raise ValueError("El stock debe ser un número entero.")
        if self.stock < 0:
            raise ValueError("El stock no puede ser negativo.")
        if not isinstance(self.moneda, str) or not re.fullmatch(
            r"[A-Za-z]{3}", self.moneda
        ):
            raise ValueError("La moneda debe tener un código de tres letras.")

        object.__setattr__(self, "id", self.id.strip())
        object.__setattr__(self, "nombre", self.nombre.strip())
        object.__setattr__(self, "moneda", self.moneda.upper())
        object.__setattr__(self, "precio", _convertir_precio(self.precio))

"""Elemento inmutable del carrito."""

from dataclasses import dataclass
from decimal import Decimal

from models.producto import Producto, redondear_monetario


def validar_cantidad(cantidad: int) -> None:
    """Exige cantidades enteras estrictamente positivas."""
    if not isinstance(cantidad, int) or isinstance(cantidad, bool):
        raise ValueError("La cantidad debe ser un número entero.")
    if cantidad <= 0:
        raise ValueError("La cantidad debe ser mayor que cero.")


@dataclass(frozen=True, slots=True)
class ItemCarrito:
    """Producto y cantidad seleccionada, con subtotal calculado."""

    producto: Producto
    cantidad: int

    def __post_init__(self) -> None:
        if not isinstance(self.producto, Producto):
            raise TypeError("El elemento debe contener un producto válido.")
        validar_cantidad(self.cantidad)
        if self.cantidad > self.producto.stock:
            raise ValueError(
                f"Stock insuficiente para '{self.producto.id}': "
                f"disponible {self.producto.stock}."
            )

    @property
    def subtotal(self) -> Decimal:
        return redondear_monetario(self.producto.precio * self.cantidad)

"""Catálogo de productos en memoria, sustituible por otra implementación."""

from collections.abc import Iterable
from dataclasses import replace

from models.producto import Producto


class ProductoNoEncontradoError(LookupError):
    """El identificador solicitado no existe en el catálogo."""


class ProductoService:
    """Administra productos sin exponer su almacenamiento interno."""

    def __init__(self, productos: Iterable[Producto] | None = None) -> None:
        self._productos: dict[str, Producto] = {}
        for producto in productos or ():
            self.agregar_producto(producto)

    def agregar_producto(self, producto: Producto) -> None:
        if not isinstance(producto, Producto):
            raise TypeError("Solo se pueden registrar productos válidos.")
        if producto.id in self._productos:
            raise ValueError(f"Ya existe un producto con id '{producto.id}'.")
        self._productos[producto.id] = producto

    def obtener_producto(self, producto_id: str) -> Producto:
        producto_id = self._normalizar_id(producto_id)
        try:
            return self._productos[producto_id]
        except KeyError as exc:
            raise ProductoNoEncontradoError(
                f"No existe el producto '{producto_id}'."
            ) from exc

    def listar_productos(self) -> tuple[Producto, ...]:
        return tuple(self._productos.values())

    def actualizar_stock(self, producto_id: str, stock: int) -> Producto:
        producto = self.obtener_producto(producto_id)
        producto_actualizado = replace(producto, stock=stock)
        self._productos[producto.id] = producto_actualizado
        return producto_actualizado

    @staticmethod
    def _normalizar_id(producto_id: str) -> str:
        if not isinstance(producto_id, str) or not producto_id.strip():
            raise ValueError("El identificador del producto es obligatorio.")
        return producto_id.strip()

"""Lógica del carrito, independiente del almacenamiento del catálogo."""

from decimal import Decimal
from typing import Protocol

from models.item_carrito import ItemCarrito, validar_cantidad
from models.producto import Producto, redondear_monetario


class CatalogoProductos(Protocol):
    """Contrato mínimo que debe cumplir cualquier catálogo inyectable."""

    def obtener_producto(self, producto_id: str) -> Producto:
        """Devuelve un producto o lanza un error si no está disponible."""
        ...


class Carrito:
    """Carrito con una única entrada por producto y validación atómica."""

    def __init__(self, catalogo: CatalogoProductos) -> None:
        if catalogo is None:
            raise ValueError("El carrito necesita un catálogo de productos.")
        self._catalogo = catalogo
        self._items: dict[str, ItemCarrito] = {}

    def agregar_producto(self, producto_id: str, cantidad: int = 1) -> ItemCarrito:
        """Añade un producto o incrementa la cantidad de su entrada actual."""
        validar_cantidad(cantidad)
        producto = self._obtener_producto(producto_id)
        self._validar_moneda(producto)

        item_actual = self._items.get(producto.id)
        cantidad_actual = item_actual.cantidad if item_actual else 0
        nuevo_item = ItemCarrito(producto, cantidad_actual + cantidad)
        self._items[producto.id] = nuevo_item
        return nuevo_item

    def actualizar_cantidad(self, producto_id: str, cantidad: int) -> ItemCarrito:
        """Sustituye la cantidad de un producto que ya está en el carrito."""
        validar_cantidad(cantidad)
        producto_id = self._normalizar_id(producto_id)
        if producto_id not in self._items:
            raise KeyError(f"El producto '{producto_id}' no está en el carrito.")

        producto = self._obtener_producto(producto_id)
        self._validar_moneda(producto)
        nuevo_item = ItemCarrito(producto, cantidad)
        self._items[producto.id] = nuevo_item
        return nuevo_item

    def quitar_producto(self, producto_id: str) -> bool:
        """Quita una entrada e indica si existía; repetir la operación es seguro."""
        producto_id = self._normalizar_id(producto_id)
        return self._items.pop(producto_id, None) is not None

    def vaciar(self) -> None:
        self._items.clear()

    def obtener_items(self) -> tuple[ItemCarrito, ...]:
        """Devuelve una instantánea inmutable en orden de inserción."""
        return tuple(self._items.values())

    def calcular_total(self) -> Decimal:
        total = sum(
            (item.subtotal for item in self._items.values()),
            start=Decimal("0.00"),
        )
        return redondear_monetario(total)

    @property
    def cantidad_total(self) -> int:
        return sum(item.cantidad for item in self._items.values())

    @property
    def moneda(self) -> str | None:
        if not self._items:
            return None
        return next(iter(self._items.values())).producto.moneda

    def _obtener_producto(self, producto_id: str) -> Producto:
        return self._catalogo.obtener_producto(self._normalizar_id(producto_id))

    def _validar_moneda(self, producto: Producto) -> None:
        if self.moneda is not None and producto.moneda != self.moneda:
            raise ValueError(
                "No se pueden mezclar monedas en el mismo carrito: "
                f"{self.moneda} y {producto.moneda}."
            )

    @staticmethod
    def _normalizar_id(producto_id: str) -> str:
        if not isinstance(producto_id, str) or not producto_id.strip():
            raise ValueError("El identificador del producto es obligatorio.")
        return producto_id.strip()

